-- ============================================================
-- PHASE 4: navigation seed (menu = discoverability only)
-- ============================================================
ALTER TABLE public.sec_navigation_items
  ADD COLUMN IF NOT EXISTS admin_only boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS required_permission_id uuid REFERENCES public.sec_permissions(id) ON DELETE RESTRICT;

CREATE TEMP TABLE _nav_seed(
  key text, parent_key text, label text, item_type text, href text,
  module_key text, action_key text, icon_key text, admin_only boolean,
  sort_order int, audience text, keywords text[]
) ON COMMIT DROP;


-- Insert level by level so parent_id can be resolved by key.
DO $$
DECLARE pass int;
BEGIN
  FOR pass IN 1..4 LOOP
       audience, admin_only, keywords, required_permission_id, is_system)
    SELECT s.key,
           parent.id,
           s.label, s.item_type, s.href, s.icon_key, s.sort_order,
           s.audience, s.admin_only, s.keywords,
           p.id,
           true
    FROM _nav_seed s
    LEFT JOIN public.sec_navigation_items parent ON parent.key = s.parent_key
    LEFT JOIN public.sec_modules m ON m.key = s.module_key
    LEFT JOIN public.sec_permissions p
      ON p.module_id = m.id AND p.key = COALESCE(s.action_key, 'view')
    WHERE NOT EXISTS (SELECT 1 FROM public.sec_navigation_items n WHERE n.key = s.key)
      AND (s.parent_key IS NULL OR parent.id IS NOT NULL);
  END LOOP;
END $$;